import gurobipy as gp
from gurobipy import GRB
products = []
revenue = {}
demand = {}
inventory = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    pname = v['Product Name']
    products.append(pname)
    try:
        revenue[pname] = float(v['Revenue'])
    except Exception:
        raise ValueError(f'Missing or invalid Revenue for {pname}')
    try:
        demand[pname] = int(v['Demand'])
    except Exception:
        raise ValueError(f'Missing or invalid Demand for {pname}')
    try:
        inventory[pname] = int(v['Initial Inventory'])
    except Exception:
        raise ValueError(f'Missing or invalid Initial Inventory for {pname}')
for pname in products:
    if pname not in revenue or pname not in demand or pname not in inventory:
        raise ValueError(f'Missing data for product {pname}')
ub = {p: min(demand[p], inventory[p]) for p in products}
m = gp.Model('Bakery_Revenue_Max')
x = m.addVars(products, lb=0, ub=ub, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[p] * x[p] for p in products)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')